-- ============================================
-- LUMA — Thème 12 : MOYEN 3/3 x4 — Participer à un atelier ponctuel
-- ============================================


update scenarios set content = '{"characters": {"instructor": "l''instructeur", "participant": "un autre participant"}, "start_node": "n1", "nodes": {"n1": {"speaker": "instructor", "text": "Welcome to our calligraphy workshop! Have you ever tried this art form before?", "text_fr": "Bienvenue à notre atelier de calligraphie ! Vous avez déjà essayé cette forme d''art auparavant ?", "choices": [{"text": "Never, I''m completely new to this.", "text_fr": "Jamais, je suis complètement nouveau à ça.", "next": "n2"}, {"text": "A little, but I''m definitely a beginner still.", "text_fr": "Un peu, mais je suis définitivement encore débutant.", "next": "n2b"}]}, "n2": {"speaker": "instructor", "text": "No worries at all, everyone starts somewhere! Let''s begin with basic strokes.", "text_fr": "Aucun souci, tout le monde commence quelque part ! Commençons par les traits de base.", "choices": [{"text": "(Follow the instructor''s demonstration carefully.)", "text_fr": "(Suis la démonstration de l''instructeur attentivement.)", "next": "n3"}]}, "n2b": {"speaker": "instructor", "text": "Great, we''ll build on whatever foundation you already have.", "text_fr": "Super, on va construire sur les bases que vous avez déjà.", "choices": [{"text": "(Practice the basic strokes shown by the instructor.)", "text_fr": "(Pratique les traits de base montrés par l''instructeur.)", "next": "n3"}]}, "n3": {"speaker": "instructor", "text": "Good start! Try to keep your wrist relaxed, let the brush do the work.", "text_fr": "Bon début ! Essayez de garder votre poignet détendu, laissez le pinceau faire le travail.", "choices": [{"text": "(Adjust your grip, focusing on relaxing your wrist.)", "text_fr": "(Ajuste ta prise, en te concentrant sur la détente de ton poignet.)", "next": "n4"}]}, "n4": {"speaker": "participant", "text": "(Nearby participant, laughing) I think I just made my letter look like a spider!", "text_fr": "(Participant à proximité, riant) Je pense que je viens de faire ressembler ma lettre à une araignée !", "choices": [{"text": "(Laugh along) Mine doesn''t look much better, honestly!", "text_fr": "(Ris aussi) La mienne a pas l''air beaucoup mieux, honnêtement !", "next": "n5"}]}, "n5": {"speaker": "instructor", "text": "That''s the spirit! Mistakes are part of learning any new art form.", "text_fr": "C''est l''esprit ! Les erreurs font partie de l''apprentissage de toute nouvelle forme d''art.", "choices": [{"text": "That''s reassuring, I was worried about getting it perfect right away.", "text_fr": "C''est rassurant, j''avais peur de devoir le faire parfait tout de suite.", "next": "n6"}]}, "n6": {"speaker": "instructor", "text": "Perfection comes with practice, not on your first try. Let''s move to full characters now.", "text_fr": "La perfection vient avec la pratique, pas au premier essai. Passons aux caractères complets maintenant.", "choices": [{"text": "(Attempt your first full character, concentrating hard.)", "text_fr": "(Tente ton premier caractère complet, en te concentrant fort.)", "next": "n7"}]}, "n7": {"speaker": "instructor", "text": "(Reviewing your work) That''s actually really well done for a first attempt!", "text_fr": "(Examinant ton travail) C''est en fait très bien fait pour une première tentative !", "choices": [{"text": "Really? Thank you, I was worried it looked messy.", "text_fr": "Vraiment ? Merci, j''avais peur que ça ait l''air brouillon.", "next": "n8"}]}, "n8": {"speaker": "instructor", "text": "Not at all, you have a natural feel for the brush strokes already.", "text_fr": "Pas du tout, vous avez déjà un sens naturel des traits de pinceau.", "choices": [{"text": "This has been such a fun and unexpected way to spend the afternoon.", "text_fr": "Ça a été une façon si amusante et inattendue de passer l''après-midi.", "next": "end_workshop"}]}, "end_workshop": {"speaker": "instructor", "text": "I''m so glad you enjoyed it! Feel free to take your work home as a souvenir.", "text_fr": "Je suis tellement content que vous ayez apprécié ! N''hésitez pas à ramener votre travail chez vous en souvenir.", "end": true, "ending_label": "Atelier de calligraphie réussi avec plaisir 🖌️😊"}}}'::jsonb, is_playable = true
where title = 'Participer à un atelier ponctuel'
  and theme_id = (select id from scenario_themes where position = 12 and language_id = (select id from languages where code = 'en'));
